package pl.zagranietyper.service;import org.junit.jupiter.api.Test;import pl.zagranietyper.model.FootballCompetitionProgressionSnapshot;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class FootballCompetitionProgressionEngineTest {private final FootballCompetitionProgressionEngine e=new FootballCompetitionProgressionEngine();@Test void singleLegHomeAwayAetAndPenalty(){assertEquals(1,e.resolve(1,1,2,"Semi",List.of(f(1,1,2,2,1,null,null,"FT"))).advancingTeam());assertEquals(2,e.resolve(1,1,2,"Semi",List.of(f(1,1,2,1,2,null,null,"AET"))).advancingTeam());var p=e.resolve(1,1,2,"Semi",List.of(f(1,1,2,1,1,3,4,"PEN")));assertEquals(2,p.advancingTeam());assertEquals(FootballCompetitionProgressionEngine.Proof.PENALTIES,p.proof());}@Test void twoLegAggregateAndOneLegWinnerLosesTie(){var r=e.resolve(2,1,2,"Semi",List.of(f(1,1,2,2,0,null,null,"FT"),f(2,2,1,3,0,null,null,"FT")));assertEquals(2,r.advancingTeam());assertEquals(FootballCompetitionProgressionEngine.Proof.AGGREGATE,r.proof());}@Test void aggregateTiePenaltyAndIncompleteAmbiguous(){assertEquals(2,e.resolve(2,1,2,"Semi",List.of(f(1,1,2,1,0,null,null,"FT"),f(2,2,1,1,0,5,4,"PEN"))).advancingTeam());assertFalse(e.resolve(1,1,2,"Semi",List.of(new FootballCompetitionProgressionSnapshot.Fixture(1,"Semi","FT","1",1L,"A",true,2L,"B",false,null,null,null,null,null,null,null,null))).resolved());assertFalse(e.resolve(1,1,2,"Semi",List.of(f(1,1,2,1,0,null,null,"FT"),f(2,2,1,1,0,null,null,"FT"),f(3,1,2,1,0,null,null,"FT"))).resolved());}@Test void inconsistentWinnerFlagsRejected(){var f=new FootballCompetitionProgressionSnapshot.Fixture(1,"Final","FT","1",1L,"A",false,2L,"B",true,2,1,2,1,null,null,null,null);assertEquals(FootballCompetitionProgressionEngine.Reason.INCONSISTENT,e.resolve(1,1,2,"Final",List.of(f)).reason());}private static FootballCompetitionProgressionSnapshot.Fixture f(long id,long h,long a,Integer hg,Integer ag,Integer ph,Integer pa,String st){return new FootballCompetitionProgressionSnapshot.Fixture(id,"Semi",st,String.valueOf(id),h,"H",hg>ag,a,"A",ag>hg,hg,ag,hg,ag,null,null,ph,pa);}}
